import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css'; // Standard calendar styles
import './AttendancePage.css'; // Our custom styles for the calendar dots

const AttendancePage = () => {
  const [allEmployees, setAllEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('All');

  // State for the modal
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [showCalendarModal, setShowCalendarModal] = useState(false);
  const [monthlyRecords, setMonthlyRecords] = useState({});

  // 1. Fetch ALL employees from the backend
  useEffect(() => {
    const fetchEmployees = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setAllEmployees(employeesData);
      } catch (error) {
        console.error("Error fetching employees:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchEmployees();
  }, []);

  // 2. Simulate today's attendance status for each real employee
  const todaysAttendance = allEmployees.map((employee, index) => ({
    ...employee,
    status: ['Present', 'Absent', 'On Leave'][index % 3],
  }));

  // 3. Filter the live data for the main table
  const filteredAttendance = todaysAttendance.filter(staff => {
    if (activeFilter === 'All') return true;
    return staff.status === activeFilter;
  });

  // 4. Function to open the calendar modal
  const handleViewAttendance = (employee) => {
    setSelectedEmployee(employee);
    // In a real app, you would fetch this data from an API:
    // e.g., axios.get(`/api/attendance/?employee=${employee.id}&month=...`)
    // For now, we simulate it.
    const records = generateMonthlyAttendance();
    setMonthlyRecords(records);
    setShowCalendarModal(true);
  };

  // Helper to get styling for status badges
  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Present': return 'bg-green-100 text-green-800';
      case 'Absent': return 'bg-red-100 text-red-800';
      case 'On Leave': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-8">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Today's Attendance</h1>
        <p className="text-sm text-subtext-light">A summary of staff and faculty attendance for today.</p>
      </div>

      <div className="mb-6 flex space-x-2">
        {/* ... (Filter buttons remain the same) ... */}
      </div>

      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm">
        {isLoading ? (
          <div className="text-center py-8 text-subtext-light">Loading employee data...</div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="text-xs uppercase bg-background-light">
              <tr>
                <th className="px-6 py-3">Staff Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Today's Status</th>
                <th className="px-6 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredAttendance.map((staff) => (
                <tr key={staff.id} className="border-b hover:bg-gray-50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-white">{staff.firstName} {staff.lastName}</td>
                  <td className="px-6 py-4">{staff.department}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(staff.status)}`}>{staff.status}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button onClick={() => handleViewAttendance(staff)} className="text-primary hover:underline text-xs font-medium">View Monthly Attendance</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Calendar Modal */}
      {showCalendarModal && (
        <CalendarModal 
          employee={selectedEmployee} 
          records={monthlyRecords} 
          closeModal={() => setShowCalendarModal(false)} 
        />
      )}
    </div>
  );
};


// --- HELPER COMPONENT FOR THE CALENDAR MODAL ---
const CalendarModal = ({ employee, records, closeModal }) => {
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white p-6 rounded-lg w-full max-w-md shadow-xl relative">
        <h2 className="text-xl font-semibold mb-4 text-gray-800">
          Monthly Attendance: {employee?.firstName} {employee?.lastName}
        </h2>

        <Calendar
          className="border-none"
          tileContent={({ date }) => {
            const status = records[date.toDateString()];
            if (status === 'Present') return <div className="calendar-dot bg-green-500"></div>;
            if (status === 'Absent') return <div className="calendar-dot bg-red-500"></div>;
            if (status === 'Half Day') return <div className="calendar-dot bg-yellow-500"></div>;
            return null;
          }}
        />

        <div className="flex justify-center space-x-4 mt-4 text-sm text-gray-600">
          <div className="flex items-center"><span className="legend-dot bg-green-500"></span>Present</div>
          <div className="flex items-center"><span className="legend-dot bg-red-500"></span>Absent</div>
          <div className="flex items-center"><span className="legend-dot bg-yellow-500"></span>Half Day</div>
        </div>

        <button onClick={closeModal} className="absolute top-4 right-4 text-gray-500 hover:text-gray-800 text-2xl">&times;</button>
      </div>
    </div>
  );
};

// Helper function to simulate monthly data
const generateMonthlyAttendance = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const records = {};
    const statuses = ['Present', 'Present', 'Present', 'Absent', 'Half Day'];
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      if (date.getDay() !== 0 && date.getDay() !== 6) { // Skip weekends
        records[date.toDateString()] = statuses[Math.floor(Math.random() * statuses.length)];
      }
    }
    return records;
};

export default AttendancePage;
